// ACQ n8n — núcleo comum (JS puro, sem require).
// Este arquivo é embutido nos nós Code do n8n pelo gerador (build/gerar.mjs) e carregado
// pelos testes locais. Tudo aqui é determinístico e não faz rede.

var ACQ_SCHEMA_VERSION = '1.0.0';
var ACQ_TZ = 'America/Sao_Paulo';

// ---------- SHA-256 / HMAC (puro, para o sandbox do n8n sem crypto) ----------
function acqUtf8Bytes(str) {
  var out = [];
  for (var i = 0; i < str.length; i++) {
    var c = str.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < str.length) {
      var d = str.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) { c = 0x10000 + ((c - 0xd800) << 10) + (d - 0xdc00); i++; }
    }
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return out;
}

var ACQ_K = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

function acqSha256Bytes(bytes) {
  var H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  var l = bytes.length;
  var msg = bytes.slice();
  msg.push(0x80);
  while ((msg.length % 64) !== 56) msg.push(0);
  var bitsHi = Math.floor((l * 8) / 0x100000000), bitsLo = (l * 8) >>> 0;
  msg.push((bitsHi >>> 24) & 255, (bitsHi >>> 16) & 255, (bitsHi >>> 8) & 255, bitsHi & 255);
  msg.push((bitsLo >>> 24) & 255, (bitsLo >>> 16) & 255, (bitsLo >>> 8) & 255, bitsLo & 255);
  var W = new Array(64);
  for (var off = 0; off < msg.length; off += 64) {
    for (var t = 0; t < 16; t++) {
      W[t] = ((msg[off + 4 * t] << 24) | (msg[off + 4 * t + 1] << 16) | (msg[off + 4 * t + 2] << 8) | msg[off + 4 * t + 3]) >>> 0;
    }
    for (t = 16; t < 64; t++) {
      var x = W[t - 15], y = W[t - 2];
      var s0 = ((x >>> 7) | (x << 25)) ^ ((x >>> 18) | (x << 14)) ^ (x >>> 3);
      var s1 = ((y >>> 17) | (y << 15)) ^ ((y >>> 19) | (y << 13)) ^ (y >>> 10);
      W[t] = (W[t - 16] + s0 + W[t - 7] + s1) >>> 0;
    }
    var a = H[0], b = H[1], c = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
    for (t = 0; t < 64; t++) {
      var S1 = ((e >>> 6) | (e << 26)) ^ ((e >>> 11) | (e << 21)) ^ ((e >>> 25) | (e << 7));
      var ch = (e & f) ^ (~e & g);
      var t1 = (h + S1 + ch + ACQ_K[t] + W[t]) >>> 0;
      var S0 = ((a >>> 2) | (a << 30)) ^ ((a >>> 13) | (a << 19)) ^ ((a >>> 22) | (a << 10));
      var maj = (a & b) ^ (a & c) ^ (b & c);
      var t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  var out = [];
  for (var i = 0; i < 8; i++) out.push((H[i] >>> 24) & 255, (H[i] >>> 16) & 255, (H[i] >>> 8) & 255, H[i] & 255);
  return out;
}

function acqHex(bytes) {
  var s = '';
  for (var i = 0; i < bytes.length; i++) s += (bytes[i] < 16 ? '0' : '') + bytes[i].toString(16);
  return s;
}

function acqSha256(str) { return acqHex(acqSha256Bytes(acqUtf8Bytes(String(str)))); }

function acqHmacSha256(key, message) {
  var k = acqUtf8Bytes(String(key));
  if (k.length > 64) k = acqSha256Bytes(k);
  while (k.length < 64) k.push(0);
  var ipad = [], opad = [];
  for (var i = 0; i < 64; i++) { ipad.push(k[i] ^ 0x36); opad.push(k[i] ^ 0x5c); }
  var inner = acqSha256Bytes(ipad.concat(acqUtf8Bytes(String(message))));
  return acqHex(acqSha256Bytes(opad.concat(inner)));
}

// Comparação em tempo constante para assinaturas hex.
function acqIguaisSeguro(a, b) {
  a = String(a || ''); b = String(b || '');
  if (a.length !== b.length || a.length === 0) return false;
  var r = 0;
  for (var i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return r === 0;
}

// ---------- JSON estável (hash de payload independe da ordem das chaves) ----------
function acqEstavel(v) {
  if (v === null || typeof v !== 'object') return JSON.stringify(v === undefined ? null : v);
  if (Array.isArray(v)) return '[' + v.map(acqEstavel).join(',') + ']';
  var ks = Object.keys(v).filter(function (k) { return v[k] !== undefined; }).sort();
  return '{' + ks.map(function (k) { return JSON.stringify(k) + ':' + acqEstavel(v[k]); }).join(',') + '}';
}

function acqHashDe(v) { return acqSha256(acqEstavel(v)); }

// UUID determinístico (formato v4-like) a partir de um texto: mesma entrada → mesmo id.
function acqUuidDe(texto) {
  var h = acqSha256(texto);
  return h.slice(0, 8) + '-' + h.slice(8, 12) + '-4' + h.slice(13, 16) + '-' +
    ((parseInt(h.slice(16, 17), 16) & 3) | 8).toString(16) + h.slice(17, 20) + '-' + h.slice(20, 32);
}

// ---------- Tempo em São Paulo ----------
// O Brasil não tem horário de verão desde 2019: São Paulo é UTC-3 fixo.
// acqConferirFuso() confirma isso pelo Intl quando disponível (testado localmente).
function acqAgoraSP(agoraMs) {
  var ms = (typeof agoraMs === 'number') ? agoraMs : Date.now();
  var d = new Date(ms - 3 * 3600 * 1000);
  var pad = function (n) { return (n < 10 ? '0' : '') + n; };
  return {
    iso_utc: new Date(ms).toISOString(),
    data: d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()),
    hora: d.getUTCHours(),
    minuto: d.getUTCMinutes(),
    dia_semana: d.getUTCDay(), // 0 domingo … 6 sábado
    ms: ms,
  };
}

function acqConferirFuso(agoraMs) {
  try {
    var f = new Intl.DateTimeFormat('en-CA', { timeZone: ACQ_TZ, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', hour12: false });
    var partes = {};
    f.formatToParts(new Date(agoraMs)).forEach(function (p) { partes[p.type] = p.value; });
    var sp = acqAgoraSP(agoraMs);
    return (partes.year + '-' + partes.month + '-' + partes.day) === sp.data && Number(partes.hour) % 24 === sp.hora;
  } catch (e) { return null; }
}

// Segunda-feira (YYYY-MM-DD) da semana de uma data YYYY-MM-DD.
function acqSegundaDaSemana(dataISO) {
  var p = dataISO.split('-').map(Number);
  var d = new Date(Date.UTC(p[0], p[1] - 1, p[2]));
  var dow = d.getUTCDay();
  var delta = dow === 0 ? -6 : 1 - dow;
  d.setUTCDate(d.getUTCDate() + delta);
  return d.toISOString().slice(0, 10);
}

function acqSomarDias(dataISO, n) {
  var p = dataISO.split('-').map(Number);
  var d = new Date(Date.UTC(p[0], p[1] - 1, p[2] + n));
  return d.toISOString().slice(0, 10);
}

function acqDiasEntre(aISO, bISO) {
  var pa = aISO.slice(0, 10).split('-').map(Number), pb = bISO.slice(0, 10).split('-').map(Number);
  return Math.round((Date.UTC(pb[0], pb[1] - 1, pb[2]) - Date.UTC(pa[0], pa[1] - 1, pa[2])) / 86400000);
}

// ---------- Texto ----------
// Mesma normalização da continuidade da Central (agente-central/continuidade.ts):
// NFD, minúsculas, só alfanumérico.
function acqChaveTexto(s) {
  return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '');
}

function acqUuidValido(s) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(s || ''));
}

// ---------- Contrato mínimo de evento ----------
var ACQ_CAMPOS_EVENTO = ['schema_version', 'event_id', 'workflow_id', 'run_id', 'client_id', 'entity_type', 'entity_id',
  'occurred_at', 'observed_at', 'source', 'source_version', 'correlation_id', 'idempotency_key', 'evidence_refs'];

// A identidade do evento vem da idempotency_key (IDs/hashes); o event_id é derivado dela.
function acqEvento(base) {
  var faltando = ['workflow_id', 'run_id', 'entity_type', 'entity_id', 'occurred_at', 'source', 'idempotency_key']
    .filter(function (k) { return base[k] === undefined || base[k] === null || base[k] === ''; });
  if (faltando.length) throw new Error('evento incompleto: ' + faltando.join(', '));
  if (base.client_id && !acqUuidValido(base.client_id)) throw new Error('evento com client_id inválido');
  var ev = {
    schema_version: ACQ_SCHEMA_VERSION,
    event_id: acqUuidDe('evento|' + base.workflow_id + '|' + base.idempotency_key),
    workflow_id: base.workflow_id,
    run_id: String(base.run_id),
    client_id: base.client_id || null,
    entity_type: base.entity_type,
    entity_id: String(base.entity_id),
    occurred_at: base.occurred_at,
    observed_at: base.observed_at || new Date().toISOString(),
    source: base.source,
    source_version: base.source_version || null,
    correlation_id: base.correlation_id || base.run_id,
    idempotency_key: base.idempotency_key,
    evidence_refs: Array.isArray(base.evidence_refs) ? base.evidence_refs : [],
    tipo: base.tipo || base.entity_type,
    payload: base.payload || {},
  };
  ev.payload_hash = acqHashDe(ev.payload);
  return ev;
}

function acqValidarEvento(ev) {
  var erros = [];
  ACQ_CAMPOS_EVENTO.forEach(function (k) { if (!(k in ev)) erros.push('falta ' + k); });
  if (ev.schema_version !== ACQ_SCHEMA_VERSION) erros.push('schema_version');
  if (!acqUuidValido(ev.event_id)) erros.push('event_id');
  if (ev.client_id !== null && !acqUuidValido(ev.client_id)) erros.push('client_id');
  if (isNaN(Date.parse(ev.occurred_at))) erros.push('occurred_at');
  if (isNaN(Date.parse(ev.observed_at))) erros.push('observed_at');
  if (!Array.isArray(ev.evidence_refs)) erros.push('evidence_refs');
  if (typeof ev.idempotency_key !== 'string' || ev.idempotency_key.length < 8 || ev.idempotency_key.length > 200) erros.push('idempotency_key');
  return erros;
}

function acqRunId(workflowId, agoraMs, semente) {
  return workflowId + ':' + new Date(agoraMs).toISOString() + ':' + acqSha256(String(semente || Math.random())).slice(0, 8);
}

// ---- lib/adaptador.js
// ACQ n8n — adaptador do MCP Aceleriq (JS puro; depende de nucleo.js).
// Decide, antes de qualquer rede, se uma chamada pode ir ao MCP, se vira simulação (dry-run)
// ou se é recusada. Depois interpreta a resposta: HTTP 200 com `error` JSON-RPC ou com
// result.isError é FALHA, nunca sucesso.

function acqConfigEfetiva(nomeAmbiente, ambientesJson) {
  var amb = ambientesJson && ambientesJson.ambientes && ambientesJson.ambientes[nomeAmbiente];
  if (!amb) throw new Error('ambiente desconhecido: ' + nomeAmbiente);
  var cfg = JSON.parse(JSON.stringify(amb));
  cfg.nome = nomeAmbiente;
  // Dry-run é o padrão. Só um "false" explícito o desliga, e o piloto nunca desliga.
  cfg.dry_run = !(amb.dry_run === false) || amb.forcar_dry_run === true || nomeAmbiente === 'pilot';
  if (nomeAmbiente === 'pilot') cfg.escritas_liberadas = [];
  cfg.escritas_liberadas = Array.isArray(cfg.escritas_liberadas) ? cfg.escritas_liberadas : [];
  return cfg;
}

// Dry-run por fluxo (comercial ACQ-06/07): dry_run_por_workflow[wf] diferente de false força
// simulação mesmo num ambiente com escrita liberada. O dry-run do ambiente vale para todos.
function acqDryRun(cfg, workflowId) {
  if (cfg.dry_run) return true;
  var m = cfg.dry_run_por_workflow;
  return !!(m && Object.prototype.hasOwnProperty.call(m, workflowId) && m[workflowId] !== false);
}

function acqEhLoopback(url) {
  return /^https?:\/\/(127\.0\.0\.1|localhost|\[::1\])(:\d+)?(\/|$)/i.test(String(url || ''));
}

function acqClassificarFerramenta(ferramenta, args, contrato) {
  args = args || {};
  if (contrato.nunca_automatico && contrato.nunca_automatico[ferramenta]) return 'proibida';
  if (contrato.leitura.indexOf(ferramenta) >= 0) return 'leitura';
  if (contrato.escrita.indexOf(ferramenta) >= 0) return 'escrita';
  if ((contrato.geracao || []).indexOf(ferramenta) >= 0) return 'geracao';
  var cond = contrato.condicionais && contrato.condicionais[ferramenta];
  if (cond) {
    if (cond.leitura_quando) {
      var ok = Object.keys(cond.leitura_quando).every(function (k) { return cond.leitura_quando[k].indexOf(args[k]) >= 0; });
      return ok ? 'leitura' : 'escrita';
    }
    if (cond.leitura_quando_sem) {
      var semCampos = cond.leitura_quando_sem.every(function (k) { return args[k] === undefined || args[k] === null || args[k] === ''; });
      return semCampos ? 'leitura' : 'escrita';
    }
  }
  return 'desconhecida';
}

// pedido: { workflow_id, run_id, ferramenta, argumentos, paginar?, ambiente_chamador, ref? }
function acqProtegerChamada(pedido, cfg, contrato) {
  var r = {
    ref: pedido.ref || null,
    workflow_id: pedido.workflow_id,
    run_id: pedido.run_id,
    ferramenta: pedido.ferramenta,
    argumentos: pedido.argumentos || {},
    paginar: pedido.paginar === true,
    ambiente: cfg.nome,
    mcp_url: cfg.mcp_url,
    decisao: 'bloquear',
    motivo: null,
    tipo: null,
    rpc: null,
    max_paginas: cfg.max_paginas || 20,
  };
  var bloquear = function (motivo) { r.decisao = 'bloquear'; r.motivo = motivo; return r; };

  if (pedido.ferramenta === 'nenhuma') return bloquear('nada_a_fazer');
  if (!pedido.workflow_id || !contrato.por_workflow[pedido.workflow_id]) return bloquear('workflow_sem_allowlist');
  if (pedido.ambiente_chamador && pedido.ambiente_chamador !== cfg.nome) return bloquear('ambiente_divergente');
  if (contrato.por_workflow[pedido.workflow_id].indexOf(pedido.ferramenta) < 0) return bloquear('ferramenta_fora_da_allowlist');
  r.tipo = acqClassificarFerramenta(pedido.ferramenta, r.argumentos, contrato);
  if (r.tipo === 'proibida' || r.tipo === 'desconhecida') return bloquear('ferramenta_' + r.tipo);
  if (cfg.exige_loopback && !acqEhLoopback(cfg.mcp_url)) return bloquear('teste_fora_do_loopback');

  // Escopo de cliente: no piloto só a Mirante. Ferramentas multi-cliente sem client_id têm o
  // resultado filtrado depois (acqFiltrarEscopo); com client_id, o id precisa estar na lista.
  // client_id_escopo: para ferramentas que recebem outro id (ex.: get_report), o chamador declara
  // o cliente esperado; ele não vai ao MCP e o resultado é conferido depois (acqConferirCliente).
  var cid = r.argumentos.client_id !== undefined ? r.argumentos.client_id : pedido.client_id_escopo;
  r.client_id_escopo = cid === undefined ? null : cid;
  if (Array.isArray(cfg.clientes_permitidos)) {
    if (cid !== undefined && cid !== null && cfg.clientes_permitidos.indexOf(cid) < 0) return bloquear('cliente_fora_do_escopo');
    if ((cid === undefined || cid === null) && contrato.multi_cliente.indexOf(pedido.ferramenta) < 0) {
      return bloquear('chamada_sem_cliente_fora_do_escopo');
    }
  }
  if (cid !== undefined && cid !== null && !acqUuidValido(cid)) return bloquear('client_id_invalido');

  if (r.tipo === 'escrita') {
    var idem = r.argumentos.idempotency_key || r.argumentos.run_key;
    // idempotencia_propria: ferramentas de esquema estrito que deduplicam sozinhas (ex.: id_externo).
    var exigeIdem = ['aceleriq_upsert_project_memory', 'aceleriq_agent_handoff', 'aceleriq_browser_act'].indexOf(pedido.ferramenta) < 0 &&
      (contrato.idempotencia_propria || []).indexOf(pedido.ferramenta) < 0;
    if (exigeIdem && (!idem || String(idem).length < 8)) return bloquear('escrita_sem_idempotency_key');
    var liberada = cfg.escritas_liberadas.indexOf(pedido.ferramenta) >= 0;
    var dry = acqDryRun(cfg, pedido.workflow_id);
    if (dry || !liberada) {
      r.decisao = 'simular';
      r.motivo = dry ? 'dry_run' : 'escrita_nao_liberada_no_ambiente';
      return r;
    }
    r.decisao = 'escrever';
  } else if (r.tipo === 'geracao') {
    // Não grava no painel, então não é simulada no dry-run; mas gasta modelo pago: vai pela via de
    // escrita (uma tentativa só, tempo longo) para nunca pagar duas vezes a mesma chamada.
    r.decisao = 'escrever';
  } else {
    r.decisao = 'ler';
  }
  if (r.paginar) {
    r.argumentos = Object.assign({}, r.argumentos);
    if (r.argumentos.offset === undefined) r.argumentos.offset = 0;
  }
  r.rpc = acqMontarRpc(pedido.ferramenta, r.argumentos, pedido.run_id);
  return r;
}

function acqMontarRpc(ferramenta, argumentos, semente) {
  return {
    jsonrpc: '2.0',
    id: 'acq-' + acqSha256(String(semente) + '|' + ferramenta + '|' + acqEstavel(argumentos)).slice(0, 16),
    method: 'tools/call',
    params: { name: ferramenta, arguments: argumentos },
  };
}

function acqSimularEscrita(req) {
  return {
    ok: true,
    simulado: true,
    dry_run: true,
    ferramenta: req.ferramenta,
    motivo: req.motivo,
    argumentos_hash: acqHashDe(req.argumentos),
    id_simulado: acqUuidDe('simulado|' + req.ferramenta + '|' + acqEstavel(req.argumentos)),
    resultado: null,
    erro: null,
  };
}

function acqClassificarMensagem(msg) {
  var m = String(msg || '');
  if (/version_conflict|CENTRAL_REPORT_VERSION_CONFLICT|versao_mudou/i.test(m)) return 'conflito_versao';
  if (/CENTRAL_SOURCE_STALE/.test(m)) return 'fonte_vencida';
  if (/CENTRAL_APPROVAL_EXPIRED/.test(m)) return 'aprovacao_vencida';
  if (/CENTRAL_ALREADY_SENT|ja_enviado/i.test(m)) return 'ja_enviado';
  if (/write:conflict|CENTRAL_IDEMPOTENCY_CONFLICT/i.test(m)) return 'conflito';
  if (/write:not_found/i.test(m)) return 'nao_encontrado';
  if (/write:forbidden|forbidden|scope/i.test(m)) return 'escopo';
  if (/write:validation|Invalid input|must be|required/i.test(m)) return 'validacao';
  if (/sessao_ocupada/i.test(m)) return 'ocupado';
  if (/timeout|timed out|ETIMEDOUT|ECONNRESET|ECONNREFUSED|socket hang up|temporar/i.test(m)) return 'transitorio';
  return 'desconhecido';
}

// httpJson: item.json produzido pelo nó HTTP (com fullResponse) ou o erro do nó (onError continue).
function acqInterpretarResposta(req, httpJson) {
  var base = { ok: false, simulado: false, ferramenta: req.ferramenta, ref: req.ref || null, resultado: null, erro: null };
  var erro = function (tipo, mensagem, extra) {
    base.erro = Object.assign({ tipo: tipo, mensagem: String(mensagem || '').slice(0, 500), pode_repetir: tipo === 'transitorio' && req.tipo === 'leitura' }, extra || {});
    return base;
  };
  if (!httpJson) return erro('payload_invalido', 'sem resposta');
  // Erro do próprio nó HTTP (rede, timeout, 4xx/5xx sem neverError).
  if (httpJson.error && !httpJson.jsonrpc && !httpJson.body) {
    var e = httpJson.error;
    var status = Number((e && (e.httpCode || e.status || e.statusCode)) || httpJson.statusCode || 0);
    var msg = (e && (e.message || e.description)) || JSON.stringify(e);
    if (status === 401) return erro('autenticacao', msg, { http_status: status });
    if (status === 403) return erro('escopo', msg, { http_status: status });
    if (status === 429 || status >= 500) return erro('transitorio', msg, { http_status: status });
    if (status >= 400) return erro('validacao', msg, { http_status: status });
    return erro(acqClassificarMensagem(msg) === 'desconhecido' ? 'transitorio' : acqClassificarMensagem(msg), msg);
  }
  var statusCode = Number(httpJson.statusCode || 200);
  var corpo = httpJson.body !== undefined ? httpJson.body : httpJson;
  if (typeof corpo === 'string') {
    try { corpo = JSON.parse(corpo.trim()); } catch (x) { return erro('payload_invalido', 'corpo não é JSON', { http_status: statusCode }); }
  }
  if (statusCode === 401) return erro('autenticacao', 'HTTP 401', { http_status: statusCode });
  if (statusCode === 403) return erro('escopo', 'HTTP 403', { http_status: statusCode });
  if (statusCode === 429 || statusCode >= 500) return erro('transitorio', 'HTTP ' + statusCode, { http_status: statusCode });
  if (!corpo || corpo.jsonrpc !== '2.0') return erro('payload_invalido', 'resposta não é JSON-RPC 2.0', { http_status: statusCode });
  if (corpo.error) {
    var c = Number(corpo.error.code);
    var tipo = c === -32001 ? 'autenticacao' : c === -32003 ? 'escopo' : c === -32004 ? 'ferramenta_inexistente'
      : c === -32602 ? 'validacao' : acqClassificarMensagem(corpo.error.message);
    return erro(tipo, corpo.error.message, { codigo: c });
  }
  var res = corpo.result;
  if (!res) return erro('payload_invalido', 'JSON-RPC sem result');
  if (res.isError) {
    var t = (res.content && res.content[0] && res.content[0].text) || 'isError';
    return erro(acqClassificarMensagem(t) === 'desconhecido' ? 'ferramenta' : acqClassificarMensagem(t), t);
  }
  var dados = res.structuredContent;
  if (dados === undefined && res.content && res.content[0] && typeof res.content[0].text === 'string') {
    try { dados = JSON.parse(res.content[0].text); } catch (x2) { return erro('payload_invalido', 'content[0].text não é JSON'); }
  }
  if (dados === undefined || dados === null || typeof dados !== 'object') return erro('payload_invalido', 'resultado vazio');
  // Algumas escritas devolvem {ok:false,status:'versao_mudou'|'ja_decidido'} em vez de erro.
  if (dados.ok === false && dados.status) return erro(acqClassificarMensagem(dados.status) === 'desconhecido' ? 'recusado' : acqClassificarMensagem(dados.status), dados.status, { resultado: dados });
  base.ok = true;
  base.resultado = dados;
  return base;
}

// Paginação offset/limit do MCP: {items,total,limit,offset,has_more,next_offset}.
function acqPlanejarPaginas(req, primeira, maxPaginas) {
  var r = primeira && primeira.resultado;
  if (!primeira || !primeira.ok || !r || r.has_more !== true) return [];
  var limit = Number(r.limit) || 25;
  var total = Number(r.total);
  var inicio = Number(r.next_offset);
  if (!isFinite(total) || !isFinite(inicio)) return [];
  var pedidos = [];
  for (var off = inicio; off < total && pedidos.length < (maxPaginas - 1); off += limit) {
    var args = Object.assign({}, req.argumentos, { offset: off, limit: limit });
    pedidos.push({ offset: off, rpc: acqMontarRpc(req.ferramenta, args, req.run_id + '|p' + off) });
  }
  return pedidos;
}

function acqJuntarPaginas(primeira, demais) {
  var r = primeira.resultado;
  var vistos = {};
  var itens = [];
  var falhas = [];
  var juntar = function (lista) {
    (lista || []).forEach(function (it) {
      var id = it && (it.id || (it.task && it.task.id) || (it.post && it.post.id));
      var chave = id ? String(id) : acqHashDe(it);
      if (!vistos[chave]) { vistos[chave] = true; itens.push(it); }
    });
  };
  juntar(r.items);
  (demais || []).forEach(function (p) {
    if (p.ok) juntar(p.resultado.items); else falhas.push(p.erro);
  });
  var total = Number(r.total);
  var completo = falhas.length === 0 && (!isFinite(total) || itens.length >= total);
  var out = Object.assign({}, r, { items: itens, has_more: false, next_offset: null, paginas_lidas: 1 + (demais || []).length });
  return { ok: completo, resultado: out, erro: completo ? null : { tipo: 'paginacao_incompleta', mensagem: 'lidos ' + itens.length + ' de ' + total, falhas: falhas, pode_repetir: true } };
}

// Filtra respostas multi-cliente para o escopo do ambiente.
function acqFiltrarEscopo(lista, cfg, campo) {
  if (!Array.isArray(cfg.clientes_permitidos)) return lista || [];
  campo = campo || 'client_id';
  return (lista || []).filter(function (x) { return x && cfg.clientes_permitidos.indexOf(x[campo]) >= 0; });
}

// Confere que um resultado lido pertence ao cliente esperado (dado de outro cliente é recusado).
function acqConferirCliente(resultado, clientIdEsperado) {
  if (!clientIdEsperado || !resultado) return true;
  var achados = [];
  (function varrer(v, prof) {
    if (!v || typeof v !== 'object' || prof > 3) return;
    if (typeof v.client_id === 'string') achados.push(v.client_id);
    Object.keys(v).forEach(function (k) { if (k !== 'distribuicao' && k !== 'sem_dia_por_nao_se_aplicar') varrer(v[k], prof + 1); });
  })(resultado, 0);
  return achados.every(function (c) { return c === clientIdEsperado; });
}

// ---- lib/comercial.js
// ACQ-06/ACQ-07 — base comum do comercial pelo WhatsApp oficial (Cloud API da Meta).
// JS puro; depende de nucleo.js e adaptador.js (acqDryRun). Nada aqui faz rede.
// O painel é a fonte da fila, das regras (horário, teto, nao_contatar) e da conversa; o n8n só
// transporta. Toda decisão sobre texto (intenção do lead) é do Jev; aqui ficam regras fixas.

var ACQ_COM_PADRAO = {
  operador: 'mercurio',
  graph_url: 'https://graph.facebook.com/v21.0',
  phone_number_id: null,
  waba_id: null,
  modelos: {},
  max_por_rodada: 5,
  retomada: { ativa: false, dias_sem_resposta: 4 },
  llm_url: 'https://openrouter.ai/api/v1/chat/completions',
  llm_modelo: 'anthropic/claude-sonnet-5.5',
  transcricao_modelo: 'google/gemini-2.5-flash',
  numero_equipe: null,
  resposta_max_caracteres: 900,
  janela_horas: 24,
  limiar_pare: 0.4,
  exigir_assinatura: true,
};

function acqComCfg(cfg) {
  var c = Object.assign({}, ACQ_COM_PADRAO, (cfg && cfg.comercial) || {});
  c.modelos = c.modelos || {};
  c.retomada = Object.assign({}, ACQ_COM_PADRAO.retomada, c.retomada || {});
  return c;
}

// O transporte só liga quando o fluxo não está em dry-run, há phone_number_id e (para modelo)
// o modelo está marcado como aprovado na config. A credencial da Meta é conferida pela própria
// chamada: sem ela o nó HTTP falha e nada é marcado como enviado.
function acqComTransporte(cfg, workflowId, modelo) {
  var c = acqComCfg(cfg);
  if (acqDryRun(cfg, workflowId)) return { ao_vivo: false, decisao: 'simular', motivo: 'dry_run' };
  if (!c.phone_number_id) return { ao_vivo: false, decisao: 'bloquear', motivo: 'falta_phone_number_id' };
  if (modelo) {
    var m = c.modelos[modelo];
    if (!m || !m.nome) return { ao_vivo: false, decisao: 'bloquear', motivo: 'modelo_sem_nome:' + modelo };
    if (m.aprovado !== true) return { ao_vivo: false, decisao: 'bloquear', motivo: 'modelo_nao_aprovado:' + modelo };
  }
  return { ao_vivo: true, decisao: 'enviar', motivo: null };
}

// Número no formato que a Cloud API usa (só dígitos com DDI). Sem "+", 10 ou 11 dígitos = Brasil.
// fixo=true para número brasileiro de 8 dígitos começando com 2 a 5 (telefone fixo, sem WhatsApp).
function acqComNumero(bruto) {
  var s = String(bruto || '').trim();
  if (!s) return null;
  var internacional = /^\+/.test(s) || /^00/.test(s.replace(/\D/g, ''));
  var d = s.replace(/\D/g, '');
  if (/^00/.test(d)) d = d.slice(2);
  if (!internacional && (d.length === 10 || d.length === 11)) d = '55' + d;
  if (d.length < 10 || d.length > 15) return null;
  var fixo = false;
  if (d.indexOf('55') === 0 && (d.length === 12 || d.length === 13)) {
    var local = d.slice(4);
    fixo = d.length === 12 && /^[2-5]/.test(local);
  } else if (d.indexOf('55') === 0) {
    return null;
  }
  return { numero: d, fixo: fixo };
}

// O wa_id que a Meta manda pode vir sem o 9 do celular brasileiro: compara DDD + 8 últimos dígitos.
function acqComMesmoNumero(a, b) {
  var na = acqComNumero(a), nb = acqComNumero(b);
  if (!na || !nb) return false;
  if (na.numero === nb.numero) return true;
  if (na.numero.indexOf('55') === 0 && nb.numero.indexOf('55') === 0) {
    return na.numero.slice(2, 4) === nb.numero.slice(2, 4) && na.numero.slice(-8) === nb.numero.slice(-8);
  }
  return false;
}

// Parâmetro de modelo: a Meta recusa quebra de linha, tabulação e mais de 4 espaços seguidos.
function acqComParametro(texto, max) {
  var t = String(texto === undefined || texto === null ? '' : texto).replace(/[\r\n\t]+/g, ' ').replace(/\s{2,}/g, ' ').trim();
  return t.slice(0, max || 200).trim();
}

function acqComNomeDoLead(item) {
  var n = acqComParametro(item && (item.empresa || item.nome), 60);
  return n.length >= 2 ? n : null;
}

// O fato observado que vai no primeiro contato. Ordem: o que alguém gravou de propósito
// (qualificacao.fato_observado), fato com prova sobre presença digital ou problema, a presença
// digital da ficha, e por fim o que a Máquina de leads registrou (sem site próprio nas fontes).
// Lead com site e sem fato gravado fica de fora: sem fato não há mensagem personalizada.
function acqComFatoObservado(item) {
  var q = (item && item.qualificacao) || {};
  // O texto entra depois de "reparei que": começa em minúscula, é uma frase só e não tem cara de anotação interna.
  var limpar = function (t) {
    var x = acqComParametro(t, 220).replace(/[.!;:,\s]+$/, '');
    if (x.length < 8 || x.length > 200) return null;
    return /^[a-zà-ú]/.test(x) && !/[;@]|\. |https?:|auditad|não testad/i.test(x) ? x : null;
  };
  var f = limpar(q.fato_observado);
  if (f) return { texto: f, fonte: 'qualificacao.fato_observado' };
  var fatos = ((item && item.fatos) || []).filter(function (x) {
    // Sugestão ainda não confirmada não vira mensagem: um fato errado dito ao dono da empresa queima o contato.
    return x && ['presenca_digital', 'problema'].indexOf(x.campo) >= 0 && x.situacao === 'gravado';
  });
  for (var i = 0; i < fatos.length; i++) {
    var v = limpar(fatos[i].valor);
    if (v) return { texto: v, fonte: 'fato:' + fatos[i].campo };
  }
  if (q.fonte === 'maquina_de_leads' && !q.site) {
    return q.instagram
      ? { texto: 'vocês têm Instagram, mas não encontrei um site próprio da empresa', fonte: 'maquina:sem_site_com_instagram' }
      : { texto: 'não encontrei um site próprio da empresa nas buscas', fonte: 'maquina:sem_site' };
  }
  return null;
}

// Texto do modelo com as variáveis, exatamente como o lead vai ler (é o que vai para a conversa).
function acqComTextoDoModelo(modelo, params) {
  var corpo = String((modelo && modelo.corpo) || '');
  return corpo.replace(/\{\{(\d+)\}\}/g, function (_, n) { return params[Number(n) - 1] === undefined ? '' : params[Number(n) - 1]; });
}

function acqComPayloadModelo(numero, modelo, params) {
  return {
    messaging_product: 'whatsapp', recipient_type: 'individual', to: numero, type: 'template',
    template: { name: modelo.nome, language: { code: modelo.idioma || 'pt_BR' },
      components: [{ type: 'body', parameters: params.map(function (p) { return { type: 'text', text: p }; }) }] },
  };
}

function acqComPayloadTexto(numero, texto) {
  return { messaging_product: 'whatsapp', recipient_type: 'individual', to: numero, type: 'text', text: { preview_url: false, body: texto } };
}

// Resposta do nó HTTP da Meta (fullResponse + neverError) ou o erro do nó (onError continue).
// aceita: a Meta devolveu o id da mensagem (wamid). recusada: a Meta disse não (nada saiu; pode
// tentar outro dia). incerta: não dá para saber se saiu (timeout, 5xx): nunca reenviar sozinho.
function acqComClassificarMeta(httpJson) {
  var r = { resultado: 'incerta', wamid: null, http_status: null, codigo: null, motivo: null, auth: false };
  if (!httpJson) { r.motivo = 'sem_resposta'; return r; }
  if (httpJson.error && httpJson.statusCode === undefined && httpJson.body === undefined) {
    var e = httpJson.error;
    var st = Number((e && (e.httpCode || e.status || e.statusCode)) || 0);
    r.http_status = st || null;
    r.motivo = String((e && (e.message || e.description)) || 'erro_do_no').slice(0, 300);
    if (st === 401 || st === 403) { r.resultado = 'recusada'; r.auth = true; return r; }
    if (st >= 400 && st < 500 && st !== 408) { r.resultado = 'recusada'; return r; }
    return r;
  }
  var st2 = Number(httpJson.statusCode || 0);
  var corpo = httpJson.body !== undefined ? httpJson.body : httpJson;
  if (typeof corpo === 'string') { try { corpo = JSON.parse(corpo); } catch (x) { corpo = null; } }
  r.http_status = st2 || null;
  var erro = corpo && corpo.error;
  if (erro) {
    r.codigo = erro.code === undefined ? null : erro.code;
    r.motivo = String(erro.message || 'erro').slice(0, 300) + (erro.error_data && erro.error_data.details ? ' | ' + String(erro.error_data.details).slice(0, 200) : '');
  }
  if (st2 >= 200 && st2 < 300 && corpo && corpo.messages && corpo.messages[0] && corpo.messages[0].id) {
    r.resultado = 'aceita'; r.wamid = String(corpo.messages[0].id); r.motivo = null; return r;
  }
  if (st2 === 401 || r.codigo === 190 || r.codigo === 10 || r.codigo === 200) { r.resultado = 'recusada'; r.auth = true; r.motivo = r.motivo || 'HTTP ' + st2; return r; }
  if (st2 === 429 || r.codigo === 4 || r.codigo === 80007 || r.codigo === 130429) { r.resultado = 'recusada'; r.motivo = r.motivo || 'limite_de_envio'; return r; }
  if (st2 >= 400 && st2 < 500) { r.resultado = 'recusada'; r.motivo = r.motivo || 'HTTP ' + st2; return r; }
  r.motivo = r.motivo || (st2 ? 'HTTP ' + st2 : 'resposta_sem_id');
  return r;
}

// Dia útil (seg a sex) e horário do comercial em São Paulo. Feriados não são conferidos aqui.
function acqComNoHorario(agoraMs, inicio, fim) {
  var sp = acqAgoraSP(agoraMs);
  var hhmm = (sp.hora < 10 ? '0' : '') + sp.hora + ':' + (sp.minuto < 10 ? '0' : '') + sp.minuto;
  var ini = String(inicio || '09:00').slice(0, 5), f = String(fim || '18:00').slice(0, 5);
  return { dia_util: sp.dia_semana >= 1 && sp.dia_semana <= 5, dentro: hhmm >= ini && hhmm < f, hora: hhmm, data: sp.data };
}

// Horário da config do painel ("09:00 a 18:00 (Sao Paulo)") → [inicio, fim].
function acqComHorarioDaFila(config) {
  var m = /(\d{2}:\d{2})\D+(\d{2}:\d{2})/.exec(String((config && config.horario) || ''));
  return m ? [m[1], m[2]] : ['09:00', '18:00'];
}

function acqComNaoContatar(item) {
  var q = (item && item.qualificacao) || {};
  return item && (item.nao_contatar === true || q.nao_contatar === true || q.nao_contatar === 'sim' || q.nao_contatar === 'true');
}

// Resultado de uma escrita no painel (saída do ACQ-00). ref = "<acao>|<id>|<lead_id>".
// Evento sempre; incidente quando falhou (alto se a mensagem já tinha saído pela Meta ou era um "pare").
function acqComResultadoEscrita(wf, r, ctx) {
  if (!r || r.ferramenta === 'nenhuma' || r.motivo === 'nada_a_fazer') return null;
  var partes = String(r.ref || '').split('|');
  var acao = partes[0] || 'escrita', id = partes[1] || 'sem_id', lead = partes[2] || null;
  var msgErro = String((r.erro && r.erro.mensagem) || '');
  var ok = r.ok === true || /Ja existe um aviso/i.test(msgErro);
  var sim = r.simulado === true;
  var ev = acqEvento({ workflow_id: wf, run_id: ctx.run_id, entity_type: 'lead', entity_id: lead || 'sem_lead',
    occurred_at: new Date(ctx.agoraMs).toISOString(), source: 'n8n:' + wf,
    idempotency_key: (wf + '|escrita|' + acao + '|' + id + (ok ? '' : '|falhou|' + String(ctx.run_id).slice(-8))).slice(0, 200),
    tipo: 'comercial_escrita_' + acao + '_' + (sim ? 'simulada' : ok ? 'ok' : 'falhou'), evidence_refs: [String(r.ferramenta)],
    payload: { ferramenta: r.ferramenta, ok: ok, simulado: sim, erro: r.erro || null, resultado: sim ? null : r.resultado,
      argumentos: r._req && r._req.argumentos ? r._req.argumentos : null } });
  var grave = ['registro', 'saida', 'parar'].indexOf(acao) >= 0;
  var inc = ok ? null : { key: (wf + '|escrita_falhou|' + acao + '|' + id).slice(0, 200), sev: grave ? 'alto' : 'aviso',
    titulo: (acao === 'parar' ? 'Pedido para parar NÃO foi gravado no painel (nao_contatar)' : acao === 'caixa' ? 'Aviso na Caixa do comercial falhou'
      : 'Mensagem saiu pela Meta mas não foi registrada no painel') + ': ' + msgErro.slice(0, 120),
    detalhe: { lead_id: lead, id: id, ferramenta: r.ferramenta, erro: r.erro || null } };
  return { evento: ev, incidente: inc };
}

// Parâmetros do nó Postgres que grava evento + incidente (+ contexto devolvido pela própria consulta).
function acqComPgEvento(evento, incidente, ambiente, contexto) {
  var p = [evento ? JSON.stringify(evento) : null, ambiente, incidente ? incidente.key : null, incidente ? incidente.sev : 'info',
    incidente ? String(incidente.titulo).slice(0, 300) : '', JSON.stringify(incidente ? incidente.detalhe || {} : {})];
  if (contexto !== undefined) p.push(JSON.stringify(contexto));
  return p;
}

// ---- lib/wf06.js
// ACQ-06 — Comercial: primeiro contato (e retomada opcional) pelo modelo aprovado da Cloud API.
// JS puro; depende de nucleo.js, adaptador.js e comercial.js.
// Regras: só lead entregue ao Mercúrio (está na fila dele), com WhatsApp, sem nao_contatar, sem lead de
// site de cliente, com fato observado, dentro do horário/dia útil e do teto do dia que o painel informa.
// Uma tentativa por lead por dia (reivindicada no Postgres antes de chamar a Meta); depois de aceita ou
// incerta, nunca mais. Erro da Meta nunca vira "enviado".

var ACQ06_TIPOS_QUE_BLOQUEIAM = {
  primeiro_contato: ['comercial_primeiro_contato_aceito', 'comercial_primeiro_contato_incerto'],
  retomada: ['comercial_retomada_aceito', 'comercial_retomada_incerto'],
};

// fila: resultado de aceleriq_comercial_fila. Devolve a regra da rodada e os candidatos em ordem.
function acq06Candidatos(fila, cfg, agoraMs) {
  var c = acqComCfg(cfg);
  var conf = (fila && fila.config) || {};
  var out = { pode: false, motivo: null, limite: 0, candidatos: [], ignorados: [] };
  if (!fila || !conf.ativo) { out.motivo = 'mercurio_desligado'; return out; }
  var h = acqComHorarioDaFila(conf);
  var agora = acqComNoHorario(agoraMs, h[0], h[1]);
  if (!agora.dia_util) { out.motivo = 'fim_de_semana'; return out; }
  if (!agora.dentro || conf.dentro_do_horario === false) { out.motivo = 'fora_do_horario'; return out; }
  var restam = Math.max(0, Number(conf.restam_hoje) || 0);
  out.limite = Math.min(restam, Math.max(0, Number(c.max_por_rodada) || 0));
  var limiteRetomada = Math.max(0, (Number(c.max_por_rodada) || 0));
  var itens = ((fila && fila.itens) || []).slice().sort(function (a, b) {
    var na = Number(a && a.qualificacao && a.qualificacao.encaixe_jev), nb = Number(b && b.qualificacao && b.qualificacao.encaixe_jev);
    return (isFinite(nb) ? nb : -1) - (isFinite(na) ? na : -1);
  });
  var prim = [], ret = [];
  itens.forEach(function (it) {
    var ign = function (m) { out.ignorados.push({ lead_id: it.lead_id, motivo: m }); };
    if (!it || !acqUuidValido(it.lead_id)) return;
    if (acqComNaoContatar(it)) return ign('nao_contatar');
    var q = it.qualificacao || {};
    if (q.client_id) return ign('lead_de_site_de_cliente');
    if (['ganho', 'perdido'].indexOf(it.etapa) >= 0) return ign('etapa_fechada');
    var msgs = it.mensagens || [];
    var entradas = msgs.filter(function (m) { return m.direcao === 'entrada'; });
    var saidas = msgs.filter(function (m) { return m.direcao === 'saida'; });
    var tipo = null;
    if (!it.primeiro_contato_feito && saidas.length === 0) {
      if (entradas.length) return ign('conversa_aberta_pelo_lead');
      tipo = 'primeiro_contato';
    } else if (c.retomada.ativa && entradas.length === 0 && saidas.length === 1) {
      var ult = Date.parse(saidas[saidas.length - 1].enviada_em);
      if (!isFinite(ult) || agoraMs - ult < Number(c.retomada.dias_sem_resposta) * 86400000) return;
      tipo = 'retomada';
    } else {
      return;
    }
    var n = acqComNumero(it.whatsapp);
    if (!n) return ign('sem_whatsapp');
    if (n.fixo) return ign('telefone_fixo');
    // 04/11/2026 (dono): celular da Máquina de leads entra mesmo sem WhatsApp confirmado. Sem WhatsApp, a Meta
    // recusa e nada chega a ninguém; fixo já saiu acima.
    var nome = acqComNomeDoLead(it);
    if (!nome) return ign('sem_nome');
    var params, fato = null;
    if (tipo === 'primeiro_contato') {
      fato = acqComFatoObservado(it);
      if (!fato) return ign('sem_fato_observado');
      params = [nome, fato.texto];
    } else {
      params = [nome];
    }
    var modelo = c.modelos[tipo] || {};
    var cand = { lead_id: it.lead_id, tipo: tipo, numero: n.numero, nome: nome, fato: fato, params: params, lead_frio: it.lead_frio === true, etapa: it.etapa,
      modelo_nome: modelo.nome || null, texto: acqComTextoDoModelo(modelo, params) };
    (tipo === 'primeiro_contato' ? prim : ret).push(cand);
  });
  prim.slice(out.limite).forEach(function (x) { out.ignorados.push({ lead_id: x.lead_id, motivo: 'teto_da_rodada' }); });
  var escolhidos = prim.slice(0, out.limite);
  escolhidos = escolhidos.concat(ret.slice(0, Math.max(0, limiteRetomada - escolhidos.length)));
  out.candidatos = escolhidos;
  out.pode = true;
  out.motivo = escolhidos.length ? null : (restam <= 0 ? 'teto_do_dia_atingido' : 'ninguem_pronto');
  return out;
}

// Evento que reivindica a tentativa do dia (ou registra a simulação). A chave impede repetir no mesmo dia.
function acq06Reivindicacao(cand, transporte, ctx) {
  var simulado = transporte.decisao === 'simular';
  var tipo = 'comercial_' + cand.tipo + (simulado ? '_simulado' : transporte.decisao === 'bloquear' ? '_bloqueado' : '_reivindicado');
  var chave = 'ACQ-06|' + cand.tipo + '|' + cand.lead_id + '|' + ctx.hoje + (simulado ? '|simulado' : transporte.decisao === 'bloquear' ? '|bloqueado' : '');
  return acqEvento({ workflow_id: 'ACQ-06', run_id: ctx.run_id, entity_type: 'lead', entity_id: cand.lead_id,
    occurred_at: new Date(ctx.agoraMs).toISOString(), source: 'n8n:ACQ-06', idempotency_key: chave, tipo: tipo,
    evidence_refs: ['aceleriq_comercial_fila'],
    payload: { tipo: cand.tipo, modelo: cand.modelo_nome, numero_final: cand.numero.slice(-4), params: cand.params, fato_fonte: cand.fato && cand.fato.fonte,
      texto: cand.texto, transporte: transporte.decisao, motivo: transporte.motivo } });
}

// Parâmetros do nó Postgres que reivindica: [lead_id, tipos que bloqueiam (csv), evento, ambiente].
function acq06PgReivindicar(cand, evento, ambiente) {
  return [cand.lead_id, ACQ06_TIPOS_QUE_BLOQUEIAM[cand.tipo].join(','), JSON.stringify(evento), ambiente];
}

// Depois da reivindicação: o que fazer com o candidato.
function acq06Envio(cand, reivindicacao, transporte, cfg) {
  var c = acqComCfg(cfg);
  var r = reivindicacao || {};
  var base = { lead_id: cand.lead_id, tipo: cand.tipo, numero: cand.numero, texto: cand.texto, modelo: cand.modelo_nome, params: cand.params, fato: cand.fato };
  if (r.bloqueado === true) return Object.assign(base, { decisao: 'pular', motivo: 'ja_enviado_ou_incerto' });
  if (r.novo !== true) return Object.assign(base, { decisao: 'pular', motivo: 'ja_tentado_hoje' });
  if (transporte.decisao !== 'enviar') return Object.assign(base, { decisao: transporte.decisao, motivo: transporte.motivo });
  var modelo = c.modelos[cand.tipo];
  return Object.assign(base, { decisao: 'enviar', motivo: null, url: String(c.graph_url).replace(/\/+$/, '') + '/' + c.phone_number_id + '/messages',
    payload: acqComPayloadModelo(cand.numero, modelo, cand.params) });
}

// Evento do desfecho do envio (aceito/recusado/incerto/simulado/bloqueado/pulado) + incidente quando cabe.
function acq06Desfecho(envio, meta, ctx) {
  var est = envio.decisao === 'enviar' ? (meta ? meta.resultado : 'incerta') : envio.decisao;
  if (est === 'pular') return { evento: null, incidente: null, estado: est };
  var nomeEst = { aceita: 'aceito', recusada: 'recusado', incerta: 'incerto', simular: 'simulado_ok', bloquear: 'bloqueado', pular: 'pulado' }[est] || est;
  var chave = 'ACQ-06|' + envio.tipo + '|' + envio.lead_id + '|' + (est === 'aceita' || est === 'incerta' ? nomeEst : ctx.hoje + '|' + nomeEst);
  var ev = acqEvento({ workflow_id: 'ACQ-06', run_id: ctx.run_id, entity_type: 'lead', entity_id: envio.lead_id,
    occurred_at: new Date(ctx.agoraMs).toISOString(), source: 'n8n:ACQ-06', idempotency_key: chave,
    tipo: 'comercial_' + envio.tipo + '_' + nomeEst, evidence_refs: meta && meta.wamid ? ['wamid:' + meta.wamid] : [],
    payload: { decisao: envio.decisao, motivo: envio.motivo, meta: meta || null, texto: envio.texto, modelo: envio.modelo, numero_final: String(envio.numero).slice(-4) } });
  var inc = null;
  if (est === 'incerta') inc = { key: 'ACQ-06|envio_incerto|' + envio.lead_id, sev: 'alto', titulo: 'Envio incerto na Cloud API: conferir no WhatsApp antes de qualquer reenvio', detalhe: { lead_id: envio.lead_id, meta: meta } };
  else if (est === 'recusada' && meta && meta.auth) inc = { key: 'ACQ-06|meta_autenticacao', sev: 'alto', titulo: 'Cloud API recusou a credencial (token/permissão)', detalhe: { meta: meta } };
  else if (est === 'recusada') inc = { key: 'ACQ-06|meta_recusou|' + (meta && meta.codigo), sev: 'aviso', titulo: 'Cloud API recusou o modelo: ' + (meta && meta.motivo || ''), detalhe: { lead_id: envio.lead_id, meta: meta } };
  else if (est === 'bloquear') inc = { key: 'ACQ-06|transporte_incompleto', sev: 'aviso', titulo: 'Transporte do WhatsApp ainda incompleto: ' + envio.motivo, detalhe: { motivo: envio.motivo } };
  return { evento: ev, incidente: inc, estado: est };
}

// O que registrar no painel depois do envio. Só o que saiu de verdade (wamid) ou a simulação do dry-run.
function acq06PedidoRegistro(envio, estado, meta, cfg, agoraMs) {
  var c = acqComCfg(cfg);
  if (estado !== 'aceita' && estado !== 'simular') return null;
  var idExterno = estado === 'aceita' ? meta.wamid : 'simulado:' + envio.tipo + ':' + envio.lead_id;
  return {
    ref: 'registro|' + idExterno + '|' + envio.lead_id,
    ferramenta: 'aceleriq_comercial_registrar_mensagem',
    argumentos: { lead_id: envio.lead_id, direcao: 'saida', texto: envio.texto, canal: 'whatsapp', enviada_em: new Date(agoraMs).toISOString(),
      id_externo: idExterno, operador: c.operador },
  };
}

